export const MIGRATIONS: { name: string; sql: string }[] = [
  { name: "001_core.sql", sql: "-- Núcleo SaaS: planes, hoteles (tenants), usuarios, membresías, sesiones, auditoría.\nCREATE EXTENSION IF NOT EXISTS btree_gist;\nCREATE EXTENSION IF NOT EXISTS citext;\n\n-- Contexto de tenant por transacción (set_config(..., true)). Sin contexto => 0 filas (falla cerrado).\nCREATE FUNCTION app_hotel_id() RETURNS uuid LANGUAGE sql STABLE AS\n  $$ SELECT nullif(current_setting('app.hotel_id', true), '')::uuid $$;\nCREATE FUNCTION app_user_id() RETURNS uuid LANGUAGE sql STABLE AS\n  $$ SELECT nullif(current_setting('app.user_id', true), '')::uuid $$;\nCREATE FUNCTION app_is_platform() RETURNS boolean LANGUAGE sql STABLE AS\n  $$ SELECT coalesce(current_setting('app.platform', true), '') = 'on' $$;\n\nCREATE TABLE plans (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  code text NOT NULL UNIQUE,\n  name text NOT NULL,\n  price_usd_cents_month integer NOT NULL CHECK (price_usd_cents_month >= 0),\n  max_rooms integer NOT NULL CHECK (max_rooms > 0),\n  max_staff integer NOT NULL CHECK (max_staff > 0),\n  features jsonb NOT NULL DEFAULT '{}'\n);\n\nCREATE TABLE hotels (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  slug text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),\n  name text NOT NULL,\n  country text NOT NULL DEFAULT 'TZ',\n  city text,\n  timezone text NOT NULL DEFAULT 'Africa/Dar_es_Salaam',\n  currencies text[] NOT NULL DEFAULT ARRAY['USD','TZS'],\n  web_languages text[] NOT NULL DEFAULT ARRAY['ro','en','es','it','fr'],\n  admin_language text NOT NULL DEFAULT 'ro',\n  plan_id uuid NOT NULL REFERENCES plans(id),\n  status text NOT NULL DEFAULT 'active' CHECK (status IN ('trial','active','suspended','cancelled')),\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\n-- Suscripción SIMULADA: no hay cobro ni pasarela conectada.\nCREATE TABLE subscriptions (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  hotel_id uuid NOT NULL REFERENCES hotels(id) ON DELETE CASCADE,\n  plan_id uuid NOT NULL REFERENCES plans(id),\n  status text NOT NULL DEFAULT 'trialing' CHECK (status IN ('trialing','active','past_due','cancelled')),\n  period_start date NOT NULL DEFAULT current_date,\n  period_end date NOT NULL DEFAULT (current_date + 30),\n  simulated boolean NOT NULL DEFAULT true CHECK (simulated),\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE users (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  email citext NOT NULL UNIQUE,\n  password_hash text NOT NULL,\n  full_name text NOT NULL,\n  locale text NOT NULL DEFAULT 'ro',\n  is_platform_admin boolean NOT NULL DEFAULT false,\n  active boolean NOT NULL DEFAULT true,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE memberships (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  hotel_id uuid NOT NULL REFERENCES hotels(id) ON DELETE CASCADE,\n  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  role text NOT NULL CHECK (role IN ('owner','manager','receptionist','housekeeping','maintenance','accountant')),\n  active boolean NOT NULL DEFAULT true,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (hotel_id, user_id)\n);\n\n-- Solo se guarda el hash SHA-256 del token de sesión.\nCREATE TABLE sessions (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  token_hash text NOT NULL UNIQUE,\n  expires_at timestamptz NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  ip text,\n  user_agent text\n);\nCREATE INDEX sessions_user_idx ON sessions(user_id);\n\n-- Auditoría append-only: la aplicación solo tiene INSERT/SELECT.\nCREATE TABLE audit_log (\n  id bigserial PRIMARY KEY,\n  hotel_id uuid REFERENCES hotels(id),\n  user_id uuid,\n  action text NOT NULL,\n  entity text,\n  entity_id text,\n  data jsonb NOT NULL DEFAULT '{}',\n  ip text,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX audit_hotel_idx ON audit_log(hotel_id, created_at DESC);\n\n-- ===== Row-Level Security =====\nALTER TABLE hotels ENABLE ROW LEVEL SECURITY;  ALTER TABLE hotels FORCE ROW LEVEL SECURITY;\nCREATE POLICY hotels_read ON hotels FOR SELECT USING (\n  id = app_hotel_id() OR app_is_platform()\n  OR EXISTS (SELECT 1 FROM memberships m WHERE m.hotel_id = hotels.id AND m.user_id = app_user_id()));\nCREATE POLICY hotels_write ON hotels FOR ALL USING (app_is_platform()) WITH CHECK (app_is_platform());\n\nALTER TABLE subscriptions ENABLE ROW LEVEL SECURITY;  ALTER TABLE subscriptions FORCE ROW LEVEL SECURITY;\nCREATE POLICY subs_read ON subscriptions FOR SELECT USING (hotel_id = app_hotel_id() OR app_is_platform());\nCREATE POLICY subs_write ON subscriptions FOR ALL USING (app_is_platform()) WITH CHECK (app_is_platform());\n\nALTER TABLE memberships ENABLE ROW LEVEL SECURITY;  ALTER TABLE memberships FORCE ROW LEVEL SECURITY;\nCREATE POLICY memb_read ON memberships FOR SELECT USING (\n  hotel_id = app_hotel_id() OR user_id = app_user_id() OR app_is_platform());\nCREATE POLICY memb_write ON memberships FOR ALL USING (hotel_id = app_hotel_id() OR app_is_platform())\n  WITH CHECK (hotel_id = app_hotel_id() OR app_is_platform());\n\nALTER TABLE audit_log ENABLE ROW LEVEL SECURITY;  ALTER TABLE audit_log FORCE ROW LEVEL SECURITY;\nCREATE POLICY audit_read ON audit_log FOR SELECT USING (hotel_id = app_hotel_id() OR app_is_platform());\nCREATE POLICY audit_insert ON audit_log FOR INSERT WITH CHECK (\n  hotel_id IS NULL OR hotel_id = app_hotel_id() OR app_is_platform());\n\n-- ===== Permisos del rol de aplicación =====\nGRANT USAGE ON SCHEMA public TO botiq_app;\nGRANT SELECT ON plans TO botiq_app;\nGRANT SELECT, INSERT, UPDATE ON hotels, subscriptions TO botiq_app;\nGRANT SELECT, INSERT, UPDATE ON users TO botiq_app;\nGRANT SELECT, INSERT, UPDATE, DELETE ON memberships, sessions TO botiq_app;\nGRANT SELECT, INSERT ON audit_log TO botiq_app;\nGRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO botiq_app;\n" },
  { name: "002_pms.sql", sql: "-- Módulo PMS. Toda tabla tiene hotel_id; las FK son compuestas (hotel_id, id) para que\n-- una fila de un hotel NUNCA pueda referenciar datos de otro hotel.\nCREATE TABLE room_types (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  hotel_id uuid NOT NULL REFERENCES hotels(id) ON DELETE CASCADE,\n  name text NOT NULL,\n  description text,\n  max_adults integer NOT NULL DEFAULT 2 CHECK (max_adults > 0),\n  max_children integer NOT NULL DEFAULT 0 CHECK (max_children >= 0),\n  base_rate_cents integer NOT NULL CHECK (base_rate_cents >= 0),\n  UNIQUE (hotel_id, id),\n  UNIQUE (hotel_id, name)\n);\n\nCREATE TABLE rooms (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  hotel_id uuid NOT NULL REFERENCES hotels(id) ON DELETE CASCADE,\n  room_type_id uuid NOT NULL,\n  number text NOT NULL,\n  floor integer NOT NULL DEFAULT 0,\n  status text NOT NULL DEFAULT 'available' CHECK (status IN ('available','out_of_service')),\n  housekeeping_status text NOT NULL DEFAULT 'clean' CHECK (housekeeping_status IN ('clean','dirty','in_progress','inspected')),\n  UNIQUE (hotel_id, id),\n  UNIQUE (hotel_id, number),\n  FOREIGN KEY (hotel_id, room_type_id) REFERENCES room_types(hotel_id, id)\n);\n\n-- Tarifas por temporada: [start_date, end_date). Sin solapes por tipo de habitación.\nCREATE TABLE rate_periods (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  hotel_id uuid NOT NULL REFERENCES hotels(id) ON DELETE CASCADE,\n  room_type_id uuid NOT NULL,\n  name text NOT NULL,\n  start_date date NOT NULL,\n  end_date date NOT NULL,\n  price_cents integer NOT NULL CHECK (price_cents >= 0),\n  CHECK (end_date > start_date),\n  UNIQUE (hotel_id, id),\n  FOREIGN KEY (hotel_id, room_type_id) REFERENCES room_types(hotel_id, id),\n  EXCLUDE USING gist (room_type_id WITH =, daterange(start_date, end_date, '[)') WITH &&)\n);\n\nCREATE TABLE guests (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  hotel_id uuid NOT NULL REFERENCES hotels(id) ON DELETE CASCADE,\n  full_name text NOT NULL,\n  email text,\n  phone text,\n  country text,\n  notes text,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (hotel_id, id)\n);\n\nCREATE TABLE reservations (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  hotel_id uuid NOT NULL REFERENCES hotels(id) ON DELETE CASCADE,\n  code text NOT NULL,\n  guest_id uuid NOT NULL,\n  room_id uuid NOT NULL,\n  room_type_id uuid NOT NULL,\n  check_in date NOT NULL,\n  check_out date NOT NULL,\n  adults integer NOT NULL DEFAULT 1 CHECK (adults > 0),\n  children integer NOT NULL DEFAULT 0 CHECK (children >= 0),\n  status text NOT NULL DEFAULT 'confirmed' CHECK (status IN ('pending','confirmed','checked_in','checked_out','cancelled','no_show')),\n  source text NOT NULL DEFAULT 'direct' CHECK (source IN ('direct','web','phone','walk_in','booking_com','airbnb','other')),\n  total_cents integer NOT NULL CHECK (total_cents >= 0),\n  currency text NOT NULL DEFAULT 'USD' CHECK (currency = 'USD'),\n  notes text,\n  created_by uuid,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now(),\n  checked_in_at timestamptz,\n  checked_out_at timestamptz,\n  CHECK (check_out > check_in),\n  UNIQUE (hotel_id, id),\n  UNIQUE (hotel_id, code),\n  FOREIGN KEY (hotel_id, guest_id) REFERENCES guests(hotel_id, id),\n  FOREIGN KEY (hotel_id, room_id) REFERENCES rooms(hotel_id, id),\n  FOREIGN KEY (hotel_id, room_type_id) REFERENCES room_types(hotel_id, id),\n  -- Garantía final contra doble reserva, incluso con peticiones concurrentes.\n  EXCLUDE USING gist (room_id WITH =, daterange(check_in, check_out, '[)') WITH &&)\n    WHERE (status IN ('pending','confirmed','checked_in'))\n);\nCREATE INDEX reservations_dates_idx ON reservations(hotel_id, check_in, check_out);\n\n-- Pagos SIMULADOS: el CHECK impide guardar un pago \"real\" hasta que exista una integración verificada.\nCREATE TABLE payments (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  hotel_id uuid NOT NULL REFERENCES hotels(id) ON DELETE CASCADE,\n  reservation_id uuid NOT NULL,\n  kind text NOT NULL DEFAULT 'payment' CHECK (kind IN ('payment','refund')),\n  amount_cents integer NOT NULL CHECK (amount_cents > 0),\n  method text NOT NULL CHECK (method IN ('cash','card_simulated','transfer')),\n  simulated boolean NOT NULL DEFAULT true CHECK (simulated),\n  reference text,\n  created_by uuid,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  FOREIGN KEY (hotel_id, reservation_id) REFERENCES reservations(hotel_id, id)\n);\n\n-- Excursiones, transfers y otros extras cargados a la reserva.\nCREATE TABLE extras (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  hotel_id uuid NOT NULL REFERENCES hotels(id) ON DELETE CASCADE,\n  reservation_id uuid NOT NULL,\n  kind text NOT NULL CHECK (kind IN ('excursion','transfer','restaurant','other')),\n  description text NOT NULL,\n  quantity integer NOT NULL DEFAULT 1 CHECK (quantity > 0),\n  unit_price_cents integer NOT NULL CHECK (unit_price_cents >= 0),\n  service_date date,\n  created_by uuid,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  FOREIGN KEY (hotel_id, reservation_id) REFERENCES reservations(hotel_id, id)\n);\n\nDO $$\nDECLARE t text;\nBEGIN\n  FOREACH t IN ARRAY ARRAY['room_types','rooms','rate_periods','guests','reservations','payments','extras'] LOOP\n    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);\n    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);\n    EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (hotel_id = app_hotel_id() OR app_is_platform()) WITH CHECK (hotel_id = app_hotel_id() OR app_is_platform())', t);\n  END LOOP;\nEND $$;\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON room_types, rooms, rate_periods, guests, extras TO botiq_app;\nGRANT SELECT, INSERT, UPDATE ON reservations TO botiq_app;\n-- Los pagos son un libro contable: sin UPDATE ni DELETE (las correcciones son reembolsos).\nGRANT SELECT, INSERT ON payments TO botiq_app;\n" },
  { name: "003_public.sql", sql: "-- Contenido público multilingüe (datos de demostración; edición futura desde el panel).\nALTER TABLE hotels ADD COLUMN public_info jsonb NOT NULL DEFAULT '{}';\nALTER TABLE room_types ADD COLUMN description_i18n jsonb NOT NULL DEFAULT '{}';\nALTER TABLE reservations ADD COLUMN guest_language text CHECK (guest_language IN ('ro','en','es','it','fr'));\nGRANT UPDATE (public_info) ON hotels TO botiq_app;\n" },
];
